namespace FantasyInformator.Tool.MapGenerator;

public static class GeneratedFiles
{
    public const string MapExtensionsClassName = "MapExtensions";

    private const string Header = """
        // <auto-generated/>
        #nullable enable
        """;

    private const string MappersNamespace = "global::FantasyInformator.Shared.Mappers";

    /// <summary>
    /// Writes the source of every file: one class per Map method, named after its source class, and one class with the
    /// generic Map method that gives its copy through out.
    /// Example: the Map method from Player to PlayerDb gives the file PlayerMapExtensions.g.cs.
    /// </summary>
    public static IReadOnlyDictionary<string, string> Create(
        IReadOnlyList<MapMethod> mapMethods,
        string extensionsNamespace)
    {
        var files = mapMethods.ToDictionary(
            x => $"{x.SourceName}{MapExtensionsClassName}.g.cs",
            x => CreateMapMethodSource(x, extensionsNamespace));

        files.Add($"{MapExtensionsClassName}.g.cs", CreateGenericMapMethodSource(extensionsNamespace));

        return files;
    }

    private static string CreateMapMethodSource(MapMethod mapMethod, string extensionsNamespace)
    {
        var className = $"{mapMethod.SourceName}{MapExtensionsClassName}";
        var source = $"global::{mapMethod.Source}";
        var target = $"global::{mapMethod.Target}";

        return $$"""
            {{Header}}

            namespace {{extensionsNamespace}};

            internal static class {{className}}
            {
                private static {{MappersNamespace}}.Mapper<{{source}}, {{target}}> Mapper =>
                    {{MappersNamespace}}.MapperLookup.Find<{{source}}, {{target}}>(typeof({{className}}).Assembly);

                public static {{target}} Map(this {{source}} source) =>
                    Mapper.Map(source);

                public static global::System.Collections.Generic.IEnumerable<{{target}}> Map(
                    this global::System.Collections.Generic.IEnumerable<{{source}}> sources) =>
                    Mapper.Map(sources);
            }

            """;
    }

    private static string CreateGenericMapMethodSource(string extensionsNamespace) =>
        $$"""
        {{Header}}

        namespace {{extensionsNamespace}};

        internal static class {{MapExtensionsClassName}}
        {
            public static void Map<TSource, TTarget>(this TSource source, out TTarget target)
                where TSource : class
                where TTarget : class =>
                target = {{MappersNamespace}}.MapperLookup
                    .Find<TSource, TTarget>(typeof({{MapExtensionsClassName}}).Assembly)
                    .Map(source);
        }

        """;
}
